// --- Função Única de Consultas (Unificada) ---
// Evita múltiplas consultas separadas quando os filtros mudam dinamicamente
function getFilteredData($conn, $filters = []) {
    $sql = "SELECT DISTINCT gre, escola, professor, id, turma FROM turmas WHERE 1=1";
    $whereParams = [];
    $types = '';

    // Validação e Construção da Cláusula WHERE
    if (!empty($filters['gre'])) {
        $placeholders = implode(',', array_fill(0, count($filters['gre']), '?'));
        $types .= str_repeat('s', count($filters['gre']));
        foreach ($filters['gre'] as $val) {
            $whereParams[] = $val;
        }
        $sql .= " AND gre IN ($placeholders)";
    }

    if (!empty($filters['escola'])) {
        $placeholders = implode(',', array_fill(0, count($filters['escola']), '?'));
        $types .= str_repeat('s', count($filters['escola']));
        foreach ($filters['escola'] as $val) {
            $whereParams[] = $val;
        }
        $sql .= " AND escola IN ($placeholders)";
    }

    if (!empty($filters['professor'])) {
        $placeholders = implode(',', array_fill(0, count($filters['professor']), '?'));
        $types .= str_repeat('s', count($filters['professor']));
        foreach ($filters['professor'] as $val) {
            $whereParams[] = $val;
        }
        $sql .= " AND professor IN ($placeholders)";
    }

    if (!empty($filters['turma'])) {
        $placeholders = implode(',', array_fill(0, count($filters['turma']), '?'));
        $types .= str_repeat('s', count($filters['turma']));
        foreach ($filters['turma'] as $val) {
            $whereParams[] = $val;
        }
        $sql .= " AND turma IN ($placeholders)";
    }

    // Preparação da Consulta Final Unificada
    $stmt = $conn->prepare($sql);
    if ($stmt === false) {
        throw new Exception("Erro na preparação da consulta SQL: " . htmlspecialchars($conn->error));
    }

    $result = $stmt->bind_param($types, ...$whereParams); // Bind todos parâmetros juntos
    $stmt->execute();
    $query = $stmt->get_result();
    $stmt->close();

    return $query;
}

